import{_ as e,H as l,f as d,i as n}from"./chunks/framework.DLd0CbzH.js";const f=JSON.parse('{"title":"Жизненный цикл закупки ЕИС и карта мониторинга","description":"","frontmatter":{"type":"reference","tags":["agelto","eis","zakupki","lifecycle","statuses","monitoring","winner"],"created":"2026-06-14T00:00:00.000Z","updated":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/Procurement_Lifecycle.md","filePath":"03_Dev/Procurement_Lifecycle.md"}'),a={name:"03_Dev/Procurement_Lifecycle.md"};function o(s,t,i,r,c,g){return l(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="жизненныи-цикл-закупки-еис-и-карта-мониторинга" tabindex="-1">Жизненный цикл закупки ЕИС и карта мониторинга <a class="header-anchor" href="#жизненныи-цикл-закупки-еис-и-карта-мониторинга" aria-label="Permalink to &quot;Жизненный цикл закупки ЕИС и карта мониторинга&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">Связанные документы</p><p>← [[Architecture_Agelto]] | ← [[BRD (Agelto)]] | → [[ADR-002_Winner_Tracking_And_Monitoring]] | → [[Risk_Register (Agelto)]]</p><p>Источник — два анализа Perplexity (2026-06-14), сведённые и сверенные с фактическим кодом (аудит 2026-06-14); исходные файлы после переноса удалены, их содержание полностью отражено здесь и в [[ADR-002_Winner_Tracking_And_Monitoring]]. Раздел §11 отделяет проверенное по коду от внешних гипотез.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">Статус знания</p><p>Пост-наградный жизненный цикл (определение победителя, контракт, мониторинг статуса закупки) в коде Agelto <strong>не реализован</strong> — текущий пайплайн заканчивается на парсинге документов закупки. Документ — справочник по предметной области и основание для [[ADR-002_Winner_Tracking_And_Monitoring|ADR-002]] (Proposed). Внешние факты (SOAP API, структура XML, статистика) помечены ⚠️ и требуют проверки на живом ЕИС до реализации.</p></div><hr><h2 id="_1-зачем-это-agelto" tabindex="-1">1. Зачем это Agelto <a class="header-anchor" href="#_1-зачем-это-agelto" aria-label="Permalink to &quot;1. Зачем это Agelto&quot;">​</a></h2><p>Agelto парсит строительные госзакупки ЕИС и извлекает из смет позиции материалов, чтобы выдавать лиды поставщику. Анализы поднимают существенный продуктовый тезис:</p><p><strong>Реальный покупатель материалов — это победитель закупки (подрядчик), а не заказчик.</strong> Заказчик (госорган) проводит тендер, но материалы по смете будет закупать тот, кто выиграет подряд. Значит лид, выданный на этапе извещения (до известности победителя), может быть <strong>преждевременным</strong>: контакт для продажи материалов — победитель, который определится позже.</p><p>Отсюда три прикладных вопроса, на которые текущая система ответить не может:</p><ol><li><strong>Когда и где появляется победитель</strong> в жизненном цикле закупки.</li><li><strong>Какие статусы означают «работа закончена»</strong> — чтобы не опрашивать мёртвые записи.</li><li><strong>Когда «завершённая» закупка снова становится активной</strong> (уклонение, отмена результата ФАС, расторжение, повтор).</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">Это меняет трактовку «лида», поэтому вынесено в [[ADR-002_Winner_Tracking_And_Monitoring|ADR-002]] как предложение, требующее бизнес-валидации. Официальный scope v1 ([[BRD (Agelto)]]) пока не меняется.</p><p></p></div><hr><h2 id="_2-нормативная-база-кратко" tabindex="-1">2. Нормативная база (кратко) <a class="header-anchor" href="#_2-нормативная-база-кратко" aria-label="Permalink to &quot;2. Нормативная база (кратко)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Закон</th><th style="text-align:left;">Кто проводит</th><th style="text-align:left;">Особенность для парсинга</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>44-ФЗ</strong></td><td style="text-align:left;">Госорганы, муниципалитеты, бюджетные учреждения</td><td style="text-align:left;">Жёсткая регламентация, стандартизированные статусы и протоколы — пригодно для автоматического чтения</td></tr><tr><td style="text-align:left;"><strong>223-ФЗ</strong></td><td style="text-align:left;">Госкорпорации, АО с госдолей &gt;50%, естественные монополии</td><td style="text-align:left;">Порядок закупки определяет сам заказчик — меньше стандартизации</td></tr></tbody></table><p>Приоритет MVP — <strong>44-ФЗ, строительные аукционы</strong>. 223-ФЗ — после пилота, отдельной реализацией.</p><hr><h2 id="_3-способы-определения-поставщика-44-фз-—-когда-появляется-победитель" tabindex="-1">3. Способы определения поставщика (44-ФЗ) — когда появляется победитель <a class="header-anchor" href="#_3-способы-определения-поставщика-44-фз-—-когда-появляется-победитель" aria-label="Permalink to &quot;3. Способы определения поставщика (44-ФЗ) — когда появляется победитель&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Способ</th><th style="text-align:left;">Критерий победы</th><th style="text-align:left;">Где победитель</th></tr></thead><tbody><tr><td style="text-align:left;">Электронный аукцион</td><td style="text-align:left;">Наименьшая цена</td><td style="text-align:left;">Протокол подведения итогов</td></tr><tr><td style="text-align:left;">Открытый конкурс (электронный)</td><td style="text-align:left;">Цена + качество</td><td style="text-align:left;">Протокол подведения итогов</td></tr><tr><td style="text-align:left;">Запрос котировок (электронный)</td><td style="text-align:left;">Наименьшая цена (НМЦК ≤ лимит)</td><td style="text-align:left;">Протокол</td></tr><tr><td style="text-align:left;">Запрос предложений</td><td style="text-align:left;">Наилучшие условия</td><td style="text-align:left;">Протокол</td></tr><tr><td style="text-align:left;">Единственный поставщик (ст.93)</td><td style="text-align:left;">Известен заранее</td><td style="text-align:left;">Реестр контрактов напрямую</td></tr></tbody></table><p>Победитель публикуется в <strong>протоколе подведения итогов</strong> (переход закупки в статус «завершена»). Для единственного поставщика — сразу в реестре контрактов.</p><hr><h2 id="_4-жизненныи-цикл-закупки-44-фз-диаграмма-состоянии" tabindex="-1">4. Жизненный цикл закупки (44-ФЗ): диаграмма состояний <a class="header-anchor" href="#_4-жизненныи-цикл-закупки-44-фз-диаграмма-состоянии" aria-label="Permalink to &quot;4. Жизненный цикл закупки (44-ФЗ): диаграмма состояний&quot;">​</a></h2><p>Сведённая карта (объединены диаграммы обоих анализов). Ветви «возврата к жизни» помечены ⮌.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ИЗВЕЩЕНИЕ ОПУБЛИКОВАНО] ──(правка)──&gt; [ИЗМЕНЕНО ИЗВЕЩЕНИЕ]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>[ПРИЁМ ЗАЯВОК] ───────────────────────────────► [ОТМЕНЕНА ЗАКАЗЧИКОМ] (терминал)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>[РАБОТА КОМИССИИ / РАССМОТРЕНИЕ ЗАЯВОК]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── мало/нет участников ─► [НЕСОСТОЯВШАЯСЯ] ⮌ повтор / ед.поставщик</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>[ПОДВЕДЕНИЕ ИТОГОВ]  ★ ПОБЕДИТЕЛЬ ОПРЕДЕЛЁН ★</span></span>
<span class="line"><span>        │   (ИНН, наименование, итоговая цена, № заявки, дата)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── жалоба в ФАС ─► [ПРИОСТАНОВЛЕНО] ⮌ возврат к рассмотрению / отмена</span></span>
<span class="line"><span>        ├── победитель не подписал ─► [УКЛОНЕНИЕ] ⮌ контракт со 2-м участником</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>[КОНТРАКТ ПОДПИСАН] ──► [ИСПОЛНЕНИЕ] ──► [ИСПОЛНЕН] (терминал)</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                              └── [РАСТОРГНУТ] ⮌ повторная закупка на остаток</span></span></code></pre></div><p>Ключ: после узла «подведение итогов» закупка формально может считаться завершённой, но фактически ещё несколько ветвей способны изменить победителя или вернуть закупку в активную фазу — это и есть зона, которую мониторинг должен покрывать.</p><hr><h2 id="_5-реестр-статусов-еис-сведенныи" tabindex="-1">5. Реестр статусов ЕИС (сведённый) <a class="header-anchor" href="#_5-реестр-статусов-еис-сведенныи" aria-label="Permalink to &quot;5. Реестр статусов ЕИС (сведённый)&quot;">​</a></h2><div class="caution custom-block github-alert"><p class="custom-block-title">Коды в столбце «Код» — **предлагаемое внутреннее обозначение**, не официальные константы ЕИС (см. §11). Достоверно — русские названия статусов, видимые на карточке/в листинге.</p><p></p></div><table tabindex="0"><thead><tr><th style="text-align:left;">Статус ЕИС (ru)</th><th style="text-align:left;">Предлаг. код</th><th style="text-align:left;">Когда наступает</th><th style="text-align:left;">Действие Agelto</th></tr></thead><tbody><tr><td style="text-align:left;">Опубликовано / Подача заявок</td><td style="text-align:left;"><code>active</code></td><td style="text-align:left;">Извещение размещено, идёт приём заявок</td><td style="text-align:left;">Парсить документы/сметы</td></tr><tr><td style="text-align:left;">Изменено извещение</td><td style="text-align:left;"><code>amending</code></td><td style="text-align:left;">Заказчик правит документацию</td><td style="text-align:left;">Перечитать карточку (триггер — <code>updatedAt</code>)</td></tr><tr><td style="text-align:left;">Работа комиссии / Рассмотрение заявок</td><td style="text-align:left;"><code>commission_work</code></td><td style="text-align:left;">Срок подачи истёк</td><td style="text-align:left;">Ждать протокол</td></tr><tr><td style="text-align:left;">Подведение итогов</td><td style="text-align:left;"><code>awaiting_winner</code></td><td style="text-align:left;">Рассматриваются заявки</td><td style="text-align:left;"><strong>Критично</strong> — ждать протокол итогов</td></tr><tr><td style="text-align:left;"><strong>Закупка завершена / Победитель определён</strong></td><td style="text-align:left;"><code>winner_found</code></td><td style="text-align:left;">Протокол итогов опубликован</td><td style="text-align:left;">★ <strong>Читать победителя</strong></td></tr><tr><td style="text-align:left;">Несостоявшаяся</td><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;">Нет/мало участников</td><td style="text-align:left;">Отслеживать повторную</td></tr><tr><td style="text-align:left;">Отменена заказчиком</td><td style="text-align:left;"><code>cancelled</code></td><td style="text-align:left;">Отзыв до окончания подачи</td><td style="text-align:left;">Архив</td></tr><tr><td style="text-align:left;">Отменена ФАС</td><td style="text-align:left;"><code>cancelled_fas</code></td><td style="text-align:left;">Решение ФАС</td><td style="text-align:left;">Архив</td></tr><tr><td style="text-align:left;">Приостановлено (ФАС)</td><td style="text-align:left;"><code>suspended</code></td><td style="text-align:left;">Жалоба принята к рассмотрению</td><td style="text-align:left;">Усиленный опрос, ждать решения</td></tr><tr><td style="text-align:left;">Уклонение победителя</td><td style="text-align:left;"><code>winner_evaded</code></td><td style="text-align:left;">Победитель не подписал контракт</td><td style="text-align:left;">★ <strong>Читать 2-го участника</strong></td></tr><tr><td style="text-align:left;">Контракт подписан</td><td style="text-align:left;"><code>contract_signed</code></td><td style="text-align:left;">Контракт размещён в реестре</td><td style="text-align:left;">Зафиксировать, снизить частоту</td></tr><tr><td style="text-align:left;">Исполнение контракта</td><td style="text-align:left;"><code>executing</code></td><td style="text-align:left;">Подрядчик выполняет работы</td><td style="text-align:left;">Редкий мониторинг (расторжение)</td></tr><tr><td style="text-align:left;">Исполнен</td><td style="text-align:left;"><code>completed</code></td><td style="text-align:left;">Обязательства выполнены</td><td style="text-align:left;">Архив</td></tr><tr><td style="text-align:left;">Контракт расторгнут</td><td style="text-align:left;"><code>terminated</code></td><td style="text-align:left;">Расторжение (ст.95)</td><td style="text-align:left;">★ <strong>Возобновить отслеживание</strong></td></tr></tbody></table><hr><h2 id="_6-маппинг-статус-еис-→-текущии-код-vs-предлагаемыи-мониторинг" tabindex="-1">6. Маппинг: статус ЕИС → текущий код vs предлагаемый мониторинг <a class="header-anchor" href="#_6-маппинг-статус-еис-→-текущии-код-vs-предлагаемыи-мониторинг" aria-label="Permalink to &quot;6. Маппинг: статус ЕИС → текущий код vs предлагаемый мониторинг&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">Главный разрыв</p><p>Текущие enum&#39;ы <code>CrawlingStatus</code> (<code>Link</code>) и <code>AnalysisStatus</code> (<code>DocumentAnalysis</code>) описывают <strong>обработку документов</strong> Agelto, а <strong>не статус самой закупки в ЕИС</strong>. После краулинга статус закупки в ЕИС больше не перечитывается. Поля <code>OrderMonitoringStatus</code> и колонок победителя в схеме нет (см. §11, [[Architecture_Agelto]] §7).</p></div><table tabindex="0"><thead><tr><th style="text-align:left;">Слой</th><th style="text-align:left;">Что описывает</th><th style="text-align:left;">Где</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CrawlingStatus</code> (pending/processing/completed/failed)</td><td style="text-align:left;">Загрузка документов карточки</td><td style="text-align:left;"><code>plt_crawler_links.status</code></td></tr><tr><td style="text-align:left;"><code>AnalysisStatus</code> (11 значений)</td><td style="text-align:left;">AI-пайплайн одного документа (стадии 2–4)</td><td style="text-align:left;"><code>plt_document_analysis.status</code></td></tr><tr><td style="text-align:left;"><code>ord_orders.status</code> (nullable string)</td><td style="text-align:left;">Снимок статуса на момент краулинга, далее не обновляется</td><td style="text-align:left;"><code>ord_orders</code></td></tr><tr><td style="text-align:left;"><strong><code>OrderMonitoringStatus</code></strong></td><td style="text-align:left;">Статус закупки в ЕИС после краулинга</td><td style="text-align:left;"><strong>отсутствует</strong> → предложено в [[ADR-002_Winner_Tracking_And_Monitoring</td></tr></tbody></table><hr><h2 id="_7-победитель-где-и-что-извлекать" tabindex="-1">7. Победитель: где и что извлекать <a class="header-anchor" href="#_7-победитель-где-и-что-извлекать" aria-label="Permalink to &quot;7. Победитель: где и что извлекать&quot;">​</a></h2><p>Победитель фиксируется в <strong>протоколе подведения итогов</strong> (вкладка «Протоколы»/«Итоги» карточки). Поля к извлечению (предлагаемая модель для <code>ord_orders</code> / <code>ord_order_winners</code>):</p><ul><li><code>winner_inn</code> — ИНН победителя</li><li><code>winner_kpp</code> — КПП (для юрлиц)</li><li><code>winner_name</code> — наименование / ФИО</li><li><code>final_price</code> — итоговая цена контракта (≤ НМЦК)</li><li><code>protocol_published_at</code> — дата протокола</li><li><code>protocol_type</code> — тип (<code>итоги</code> / <code>уклонение</code> / <code>несостоявшаяся</code>)</li></ul><p><strong>Типология протоколов</strong> (⚠️ XML-типы — гипотезы анализа, проверить на живом ЕИС):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Протокол</th><th style="text-align:left;">Когда публикуется</th><th style="text-align:left;">Что извлекать</th></tr></thead><tbody><tr><td style="text-align:left;">Рассмотрение 1-х частей заявок</td><td style="text-align:left;">До аукциона, след. раб. день</td><td style="text-align:left;">Допущенные/отклонённые (ИНН)</td></tr><tr><td style="text-align:left;">Проведение электронного аукциона</td><td style="text-align:left;">~30 мин после окончания</td><td style="text-align:left;">Ценовые предложения, ИНН лидера</td></tr><tr><td style="text-align:left;"><strong>Подведение итогов</strong></td><td style="text-align:left;">След. раб. день</td><td style="text-align:left;"><strong>Победитель: ИНН, итоговая цена, дата</strong></td></tr><tr><td style="text-align:left;">Об уклонении победителя</td><td style="text-align:left;">След. раб. день</td><td style="text-align:left;">Уклонившийся → переход ко 2-му</td></tr><tr><td style="text-align:left;">Заключение со 2-м участником</td><td style="text-align:left;">После уклонения</td><td style="text-align:left;">ИНН нового победителя</td></tr><tr><td style="text-align:left;">О признании несостоявшейся</td><td style="text-align:left;">В тот же день</td><td style="text-align:left;">Причина</td></tr></tbody></table><div class="caution custom-block github-alert"><p class="custom-block-title">⚠️ Конкретная XML-структура протокола (теги \`protocolEF2Data\`, \`applicationInfo\`, \`resultStatus=WIN\` и т.п.) — внешнее непроверенное утверждение анализа. Перед реализацией парсера проверить реальный ответ ЕИС. Подтверждены кодом только страницы \`/common-info.html\` и \`/documents.html\` (используются в \`EisCrawlingService\`).</p><p></p></div><hr><h2 id="_8-сценарии-«возврата-к-жизни»" tabindex="-1">8. Сценарии «возврата к жизни» <a class="header-anchor" href="#_8-сценарии-«возврата-к-жизни»" aria-label="Permalink to &quot;8. Сценарии «возврата к жизни»&quot;">​</a></h2><p>Закупка, формально «завершённая», может потребовать повторного мониторинга.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Сценарий</th><th style="text-align:left;">Триггер</th><th style="text-align:left;">Предлагаемое действие Agelto</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Уклонение победителя</strong></td><td style="text-align:left;">Победитель не подписал контракт в срок; «Протокол об уклонении»</td><td style="text-align:left;">Перечитать карточку при изменении <code>updatedAt</code>; обновить победителя на 2-го участника или null; усилить опрос</td></tr><tr><td style="text-align:left;"><strong>Обжалование в ФАС</strong></td><td style="text-align:left;">Участник подал жалобу; закупка приостановлена</td><td style="text-align:left;">Отдельный статус <code>suspended</code>; приоритетный перечёт при <code>updatedAt &gt; submissionEndAt</code>; возможна смена победителя</td></tr><tr><td style="text-align:left;"><strong>Несостоявшаяся → повторная</strong></td><td style="text-align:left;">Нет/мало заявок; новое извещение (обычно новый <code>reg_number</code>)</td><td style="text-align:left;">Хранить в <code>failed</code> (не архив); искать связанное извещение по <code>customer_id</code> + предмету</td></tr><tr><td style="text-align:left;"><strong>Расторжение контракта</strong></td><td style="text-align:left;">Одностороннее/по соглашению/по суду (ст.95)</td><td style="text-align:left;">Мониторинг записей в <code>executing</code>; при расторжении — ждать повторную закупку</td></tr><tr><td style="text-align:left;"><strong>Изменение условий / доп.соглашение</strong></td><td style="text-align:left;">Доп.соглашение (ст.95): цена/объём/срок</td><td style="text-align:left;">Некритично (победитель не меняется), но важно для аналитики</td></tr></tbody></table><p>⚠️ Частота уклонений «3–5% аукционов» — внешняя оценка анализа, не подтверждена.</p><hr><h2 id="_9-временные-рамки-для-планировщика-опросов" tabindex="-1">9. Временные рамки (для планировщика опросов) <a class="header-anchor" href="#_9-временные-рамки-для-планировщика-опросов" aria-label="Permalink to &quot;9. Временные рамки (для планировщика опросов)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Событие</th><th style="text-align:left;">Срок по 44-ФЗ</th></tr></thead><tbody><tr><td style="text-align:left;">Публикация извещения → окончание приёма</td><td style="text-align:left;">≥7 дней (аукцион), ≥4 рабочих дня (запрос котировок)</td></tr><tr><td style="text-align:left;">Окончание приёма → протокол итогов</td><td style="text-align:left;">≤2 рабочих дня (рассмотрение)</td></tr><tr><td style="text-align:left;">Протокол итогов → подписание контракта</td><td style="text-align:left;">≥10 дней (общий случай), ≥2 дня (запрос котировок)</td></tr><tr><td style="text-align:left;">Уклонение → контракт со 2-м участником</td><td style="text-align:left;">≥10 дней</td></tr><tr><td style="text-align:left;">Жалоба в ФАС → решение</td><td style="text-align:left;">~5 рабочих дней</td></tr></tbody></table><p>Предлагаемое расписание опроса по статусу (из анализа, как ориентир): <code>active</code> 4–6 ч · <code>awaiting_winner</code> 1 ч · <code>winner_found</code> 1 раз/сутки (14 дней) · <code>executing</code> раз в 7 дней · <code>failed</code>/<code>cancelled</code>/<code>terminated</code> раз в 3–7 дней · <code>completed</code> раз в 30 дней.</p><div class="caution custom-block github-alert"><p class="custom-block-title">⚠️ Предлагаемые ориентиры мониторинга (внешние, непроверенные)</p><p></p><ul><li><strong>Freshness победителя</strong> ≤ 2 ч после протокола итогов (отсюда интервал <code>awaiting_winner</code> = 1 ч).</li><li><strong>Покрытие возвратных сценариев</strong> 100% для <code>winner_fixed</code> / <code>executing</code> / <code>completed</code>.</li><li><strong>Retention</strong> истории статусов ≥ 3 года.</li><li><strong>Связывание повторной</strong> закупки с исходной ≤ 48 ч (по <code>customer_id</code> + предмету).</li><li>Эвристика открытых парсеров: «дата торгов + 3 раб. дня → опрос итогового протокола».</li><li>Паттерн Prozorro: cursor-based синхронизация — запрашивать только изменившиеся с последней проверки.</li></ul></div><hr><h2 id="_10-доступ-к-данным-еис-html-vs-soap-api-⚠️" tabindex="-1">10. Доступ к данным ЕИС: HTML vs SOAP API ⚠️ <a class="header-anchor" href="#_10-доступ-к-данным-еис-html-vs-soap-api-⚠️" aria-label="Permalink to &quot;10. Доступ к данным ЕИС: HTML vs SOAP API ⚠️&quot;">​</a></h2><div class="caution custom-block github-alert"><p class="custom-block-title">Весь раздел — внешние непроверенные утверждения исходного анализа (Perplexity). Использовать как гипотезу при проектировании, проверить на живом ЕИС.</p><p></p></div><ul><li>Текущая реализация Agelto — <strong>headless-парсинг HTML</strong> zakupki.gov.ru (проверено: <code>EisCrawlingService</code>).</li><li>Анализ утверждает: FTP XML-выгрузки закрыты с 01.01.2025; SOAP API сменил домен на <code>int.zakupki.gov.ru</code> с 04.10.2025; для организаций — <code>int44-ttls-cert.zakupki.gov.ru</code> (ГОСТ + двусторонняя аутентификация).</li><li>SOAP требует токена (физлицо — через Госуслуги) или ЭЦП (организация) + ГОСТ-шифрование (КриптоПро).</li><li>Релевантные методы (по анализу): <code>getDocsByReestrNumberRequest</code> (документы по <code>reestrNumber</code>=<code>reg_number</code>), <code>getNsiRequest</code> (справочники). Ответ — <code>archiveUrl</code> → ZIP с XML.</li><li>Релевантные <code>documentType44</code> (по анализу): <code>epNotificationEF2020</code> (извещение), <code>epProtocolEF22020</code> (протокол итогов → победитель), <code>epProtocolEvasion</code> (уклонение), <code>epContract</code>, <code>epContractTermination</code>.</li></ul><p><strong>Гибридная стратегия (предложение):</strong> HTML-листинг для обнаружения новых закупок + SOAP по <code>reg_number</code> для деталей (протоколы, победитель, контракт). Развилка фиксируется в [[ADR-002_Winner_Tracking_And_Monitoring|ADR-002]].</p><hr><h2 id="_11-достоверность-источника" tabindex="-1">11. Достоверность источника <a class="header-anchor" href="#_11-достоверность-источника" aria-label="Permalink to &quot;11. Достоверность источника&quot;">​</a></h2><blockquote><p>[!success] ✅ Проверено по коду (аудит 2026-06-14, сверка с миграциями и классами)</p><ul><li>Пайплайн стадий 1–4, их код, очереди Horizon, state-машина/лизинг/retry/Telegram-алерты.</li><li>enum&#39;ы: <code>AnalysisStatus</code> (11), <code>CrawlingStatus</code> (4), <code>ProcessStage</code> (4), <code>PipelineStage</code> (3).</li><li><code>EisCrawlingService</code>: рекурсивное дробление по ценам (стоп при разнице &lt;10000 ₽), архивный/оперативный режимы, <code>keepStateOnCrash</code>, <code>parseAttachments</code> → <code>documents.html</code>, дедуп по <code>reg_number</code>, задержки ~3 с.</li><li><code>CrawlingItemDto</code>: <code>externalId</code>, <code>url</code>, <code>subject</code>, <code>price</code>, <code>publishedAt</code>, <code>updatedAt</code>, <code>submissionEndAt</code>, <code>attachments</code>.</li><li>Схема <code>ord_orders</code> / <code>ord_lots</code> / <code>ord_purchase_objects</code> / <code>ord_customers</code> (см. [[Architecture_Agelto]] §7).</li><li><strong>Отсутствуют</strong> (подтверждено): поля победителя/контракта, <code>OrderMonitoringStatus</code>, таблица <code>ord_order_winners</code>, <code>OrderStatusMonitorJob</code>, любой парсер протокола. <code>OrderParsingProcess::run()</code> — пустая заглушка.</li></ul></blockquote><div class="caution custom-block github-alert"><p class="custom-block-title">⚠️ Внешнее, непроверенное (гипотезы Perplexity — проверить на живом ЕИС до реализации)</p><p></p><ul><li><strong>Коды статусов ЕИС</strong> (<code>PUBLISHED</code>, <code>WINNER_DETERMINED</code>, <code>RESULTS_DETERMINATION</code> …) — предложены анализом, не подтверждены как реальные константы.</li><li><strong>SOAP API</strong>: домены <code>int.zakupki.gov.ru</code> / <code>int44-ttls-cert</code>, закрытие FTP 01.01.2025, смена домена 04.10.2025, токен через Госуслуги, ГОСТ/КриптоПро (весь §10).</li><li><strong>XML-структура протоколов</strong>: теги <code>protocolEF2Data</code> / <code>applicationInfo</code> / <code>resultStatus=WIN</code>, коды <code>documentType44</code> (§7, §10).</li><li><strong>HTML-страницы карточки</strong>: <code>/protocols.html</code>, <code>/complaints.html</code> (наличие не проверено; <code>/common-info.html</code> и <code>/documents.html</code> — проверены).</li><li><strong>Статистика</strong>: «3–5% уклонений», лимиты Тендерплан (250/10 с, 800/60 с), Prozorro «синк раз в 5 мин».</li></ul></div><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Анализ Perplexity «Схемы госзакупок ЕИС — полный анализ и карта парсинга» (2026-06-14) — бизнес/жизненный цикл, реестр статусов, логика мониторинга. <em>(исходный файл распарсен в этот документ и удалён)</em></li><li>Анализ Perplexity «Agelto × ЕИС — углублённый технический анализ» (2026-06-14) — XML-протоколы, SOAP API, gap-анализ кода, миграция HTML→SOAP. <em>(исходный файл распарсен в этот документ и удалён)</em></li><li>Аудит сверки с кодом — 3 Explore-прохода по миграциям, enum&#39;ам, <code>EisCrawlingService</code>, моделям <code>Order/*</code> (2026-06-14).</li></ul>`,60)])])}const y=e(a,[["render",o]]);export{f as __pageData,y as default};
